// Build the live template list string for the Claude prompt
const items = $input.all();
const templates = items.map(i => i.json);

const useCase     = $('Webhook').first().json.body.use_case;
const industry    = $('Webhook').first().json.body.industry;
const meetingType = $('Webhook').first().json.body.meeting_type;
const token       = $('Get Atlas Token').first().json.access_token;

// Format live templates for the prompt
const templateList = templates
  .map(t => `- "${t.template_name}" — rules: ${(t.llm_firewall_rules || []).map(r => r.rule_type).join(', ')}`)
  .join('\n');

const systemPrompt = `You are an Atlas AI Security Platform demo specialist. Given a customer use case, you analyze it and recommend Atlas runtime protection templates.
You MUST return ONLY valid JSON — no markdown, no explanation, just the JSON object.

Atlas has these LIVE templates (use exact names as listed):
${templateList}

Return this exact JSON structure:
{
  "existing_matches": [
    {
      "template_name": "<exact template name from list above>",
      "match_score": <integer 0-100>,
      "match_reason": "<one sentence why this fits>",
      "rules_included": ["<rule1>", "<rule2>"]
    }
  ],
  "custom_recommendation": {
    "suggested_name": "<custom template name>",
    "description": "<one sentence describing the custom template>",
    "rules": [
      { "rule_type": "<rule name>", "reason": "<why this rule applies>" }
    ]
  },
  "recommendation": "<existing or custom>",
  "recommendation_reason": "<one sentence explaining the overall recommendation>"
}

Include 2-3 existing_matches ranked by score. Always include a custom_recommendation even if existing templates fit well.`;

const userMessage = `Customer Use Case: ${useCase}\nIndustry: ${industry}\nMeeting Type: ${meetingType}`;

// Call Claude directly with the live template list
const claudeRes = await this.helpers.request({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': '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',
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-6',
    max_tokens: 2048,
    system: systemPrompt,
    messages: [{ role: 'user', content: userMessage }]
  })
});

const parsed = JSON.parse(claudeRes);
const text = parsed.content[0].text;

return [{ json: { text } }];

const raw = $input.first().json.text;
const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
return [{ json: JSON.parse(cleaned) }];
